18	/****************************************************************************
19	 * FreeType 字体初始化
20	 ****************************************************************************/
21	
22	#if LV_USE_FREETYPE
23	
24	/* FreeType 字体对象（需要保持存活） */
25	
26	static lv_font_t *g_ft_font_28 = NULL;
27	static lv_font_t *g_ft_font_20 = NULL;
28	static lv_font_t *g_ft_font_16 = NULL;
29	static lv_font_t *g_ft_font_14 = NULL;
