31	static lv_font_t *create_ft_font(const char *path, uint16_t size)
32	{
33	  lv_font_t *font = lv_freetype_font_create(path,
34	                                            LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
35	                                            size,
36	                                            LV_FREETYPE_FONT_STYLE_NORMAL);
37	  if (font == NULL)
38	    {
39	      printf("ERROR: Failed to create FreeType font %s at %dpx\n", path, size);
40	    }
41	  else
42	    {
43	      printf("FreeType font loaded: %s at %dpx\n", path, size);
44	    }
45	
46	  return font;
47	}
