50	
51	int ui_font_init(void)
52	{
53	#if LV_USE_FREETYPE
54	  lv_result_t res;
55	
56	  printf("Initializing FreeType library...\n");
57	
58	  /* 初始化 FreeType 库（如果已初始化则跳过） */
59	
60	  res = lv_freetype_init(256);  /* 缓存 256 个字形 */
61	  if (res != LV_RESULT_OK)
62	    {
63	      printf("FreeType already initialized, reusing existing context.\n");
64	    }
65	
66	  printf("FreeType library initialized. Loading fonts from %s...\n",
67	         FONT_PATH_MISANS);
68	
69	  /* 检查字体文件是否存在 */
70	
71	  FILE *f = fopen(FONT_PATH_MISANS, "rb");
72	  if (f == NULL)
73	    {
74	      printf("ERROR: Font file not found: %s\n", FONT_PATH_MISANS);
75	      printf("Please ensure the font file is in the ROM filesystem.\n");
76	      goto use_builtin_fonts;
77	    }
78	  fclose(f);
79	  printf("Font file found: %s\n", FONT_PATH_MISANS);
80	
81	  g_ft_font_28 = create_ft_font(FONT_PATH_MISANS, 28);
82	  g_ft_font_20 = create_ft_font(FONT_PATH_MISANS, 20);
83	  g_ft_font_16 = create_ft_font(FONT_PATH_MISANS, 16);
84	  g_ft_font_14 = create_ft_font(FONT_PATH_MISANS, 14);
85	
86	  /* 设置全局字体指针 */
87	
88	  font_cn_large  = g_ft_font_28 ? g_ft_font_28 : &lv_font_montserrat_28;
89	  font_cn_medium = g_ft_font_20 ? g_ft_font_20 : &lv_font_montserrat_20;
90	  font_cn_small  = g_ft_font_16 ? g_ft_font_16 : &lv_font_montserrat_16;
91	  font_cn_tiny   = g_ft_font_14 ? g_ft_font_14 : &lv_font_montserrat_14;
92	
93	  if (g_ft_font_28 && g_ft_font_20 && g_ft_font_16 && g_ft_font_14)
94	    {
95	      printf("All FreeType fonts loaded successfully.\n");
96	      return 0;
97	    }
98	
99	  printf("WARNING: Some fonts failed to load, using fallback.\n");
100	  return -1;
101	
102	use_builtin_fonts:
103	#else
104	  printf("FreeType not enabled, using built-in fonts (no Chinese support).\n");
105	#endif
106	
107	  font_cn_large  = &lv_font_montserrat_28;
108	  font_cn_medium = &lv_font_montserrat_20;
109	  font_cn_small  = &lv_font_montserrat_16;
110	  font_cn_tiny   = &lv_font_montserrat_14;
111	  return 0;
112	}
113	
114	void ui_font_deinit(void)
115	{
116	#if LV_USE_FREETYPE
117	  if (g_ft_font_28) lv_freetype_font_delete(g_ft_font_28);
118	  if (g_ft_font_20) lv_freetype_font_delete(g_ft_font_20);
119	  if (g_ft_font_16) lv_freetype_font_delete(g_ft_font_16);
120	  if (g_ft_font_14) lv_freetype_font_delete(g_ft_font_14);
121	
122	  g_ft_font_28 = NULL;
123	  g_ft_font_20 = NULL;
124	  g_ft_font_16 = NULL;
125	  g_ft_font_14 = NULL;
126	  font_cn_large  = NULL;
127	  font_cn_medium = NULL;
128	  font_cn_small  = NULL;
129	  font_cn_tiny   = NULL;
130	
131	  lv_freetype_uninit();
132	#endif
133	}
