147	
148	  while (1)
149	    {
150	      idle = lv_timer_handler();
151	      idle = idle ? idle : 1;
152	      usleep(idle * 1000);
153	    }
154	
155	  /* 清理（实际上不会执行到） */
156	
157	  ui_font_deinit();
158	  lv_nuttx_deinit(&result);
159	  lv_deinit();
160	
161	  return 0;
162	}
