1	/****************************************************************************
2	 * clock_widget.c — 时钟组件（RTC 实时更新）
3	 *
4	 * 功能：
5	 *   - 读取 /dev/rtc0 获取当前时间
6	 *   - 大字显示时间 HH:MM:SS
7	 *   - 显示日期 YYYY-MM-DD
8	 *   - 显示星期
9	 *   - 每秒自动刷新
10	 *
11	 * Contest 2026 Team 307
12	 ****************************************************************************/
13	
14	#include <nuttx/config.h>
15	#include <sys/ioctl.h>
16	#include <fcntl.h>
17	#include <unistd.h>
18	#include <stdio.h>
19	#include <string.h>
20	#include <nuttx/timers/rtc.h>
21	
22	#include "ui_common.h"
23	#include "clock_widget.h"
24	
25	/****************************************************************************
26	 * 私有数据
27	 ****************************************************************************/
28	
29	static lv_obj_t *g_time_label  = NULL;
30	static lv_obj_t *g_date_label  = NULL;
31	static lv_obj_t *g_week_label  = NULL;
32	static lv_timer_t *g_timer     = NULL;
33	
34	static const char *g_weekdays[] =
35	{
36	  "周日", "周一", "周二", "周三", "周四", "周五", "周六"
37	};
38	
39	/****************************************************************************
40	 * 读取 RTC 时间
41	 ****************************************************************************/
42	
43	static int rtc_read(struct rtc_time *rt)
44	{
45	  int fd = open("/dev/rtc0", O_RDONLY);
46	  if (fd < 0) return -1;
47	
48	  int ret = ioctl(fd, RTC_RD_TIME, (unsigned long)rt);
49	  close(fd);
50	  return ret;
51	}
52	
53	/****************************************************************************
54	 * 更新显示
55	 ****************************************************************************/
56	
57	static void clock_update_cb(lv_timer_t *timer)
58	{
59	  struct rtc_time rt;
60	  char buf[32];
61	
62	  if (rtc_read(&rt) < 0)
63	    return;
64	
65	  /* 时间 HH:MM:SS */
66	
67	  snprintf(buf, sizeof(buf), "%02d:%02d:%02d",
68	           rt.tm_hour, rt.tm_min, rt.tm_sec);
69	  lv_label_set_text(g_time_label, buf);
70	
71	  /* 日期 YYYY-MM-DD */
72	
73	  snprintf(buf, sizeof(buf), "%04d-%02d-%02d",
74	           rt.tm_year + 1900, rt.tm_mon + 1, rt.tm_mday);
75	  lv_label_set_text(g_date_label, buf);
76	
77	  /* 星期 */
78	
79	  if (rt.tm_wday >= 0 && rt.tm_wday <= 6)
80	    lv_label_set_text(g_week_label, g_weekdays[rt.tm_wday]);
81	}
82	
83	/****************************************************************************
84	 * 公开接口
85	 ****************************************************************************/
86	
87	lv_obj_t *clock_widget_create(lv_obj_t *parent)
88	{
89	  /* 容器 */
90	
91	  lv_obj_t *cont = lv_obj_create(parent);
92	  lv_obj_set_size(cont, 350, 160);
93	  lv_obj_set_style_bg_color(cont, COLOR_BG_CARD, 0);
94	  lv_obj_set_style_bg_opa(cont, LV_OPA_COVER, 0);
95	  lv_obj_set_style_radius(cont, 16, 0);
96	  lv_obj_set_style_border_width(cont, 0, 0);
97	  lv_obj_set_style_pad_all(cont, 20, 0);
98	  lv_obj_remove_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
99	  lv_obj_align(cont, LV_ALIGN_TOP_MID, 0, 30);
100	
101	  /* Flex 布局：垂直居中 */
102	
103	  lv_obj_set_flex_flow(cont, LV_FLEX_FLOW_COLUMN);
104	  lv_obj_set_flex_align(cont, LV_FLEX_ALIGN_CENTER,
105	                         LV_FLEX_ALIGN_CENTER,
106	                         LV_FLEX_ALIGN_CENTER);
107	  lv_obj_set_style_pad_row(cont, 8, 0);
108	
109	  /* 时间（大字） */
110	
111	  g_time_label = ui_create_label(cont, "00:00:00",
112	                                 FONT_LARGE, COLOR_TEXT_WHITE);
113	  lv_obj_set_style_text_letter_space(g_time_label, 4, 0);
114	
115	  /* 日期 */
116	
117	  g_date_label = ui_create_label(cont, "2026-01-01",
118	                                 FONT_MEDIUM, COLOR_TEXT_GRAY);
119	
120	  /* 星期 */
121	
122	  g_week_label = ui_create_label(cont, "周一",
123	                                 FONT_SMALL, COLOR_TEXT_GREEN);
124	
125	  /* 启动定时器：每秒刷新 */
126	
127	  g_timer = lv_timer_create(clock_update_cb, 1000, NULL);
128	  lv_timer_ready(g_timer);  /* 立即触发首次更新 */
129	
130	  return cont;
131	}
