2	 * Contest 2026 team 307 - My AI Tool
3	 *
4	 * 功能：
5	 *   - hello: 打招呼
6	 *   - info: 显示系统信息
7	 *   - popup <title> <content>: 显示弹窗（用于 AI Agent 触发）
8	 ****************************************************************************/
9	
10	#include <stdio.h>
11	#include <string.h>
12	#include <lvgl/lvgl.h>
13	#include <unistd.h>
14	
15	/****************************************************************************
16	 * 弹窗数据结构
17	 ****************************************************************************/
18	
19	typedef struct {
20	  char title[128];
21	  char content[256];
22	} popup_data_t;
23	
24	/****************************************************************************
25	 * LVGL 事件回调
26	 ****************************************************************************/
27	
28	static void popup_btn_close_cb(lv_event_t *e)
29	{
30	  lv_obj_t *overlay = (lv_obj_t *)lv_event_get_user_data(e);
31	  if (overlay) lv_obj_del(overlay);
32	}
33	
34	static void popup_overlay_close_cb(lv_event_t *e)
35	{
36	  lv_obj_t *overlay = (lv_obj_t *)lv_event_get_target(e);
37	  if (overlay) lv_obj_del(overlay);
38	}
39	
40	/****************************************************************************
41	 * LVGL 异步回调（在 LVGL 线程中执行）
42	 ****************************************************************************/
43	
44	static void popup_async_cb(void *data)
45	{
46	  popup_data_t *popup_data = (popup_data_t *)data;
47	  if (!popup_data) return;
48	
49	  lv_obj_t *scr = lv_screen_active();
50	  if (!scr) {
51	    free(popup_data);
52	    return;
53	  }
54	
55	  /* 创建全屏遮罩 */
56	
57	  lv_obj_t *overlay = lv_obj_create(scr);
58	  lv_obj_set_size(overlay, 390, 450);
59	  lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
60	  lv_obj_set_style_bg_opa(overlay, LV_OPA_80, 0);
61	  lv_obj_set_style_border_width(overlay, 0, 0);
62	  lv_obj_set_style_radius(overlay, 0, 0);
63	  lv_obj_remove_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
64	  lv_obj_align(overlay, LV_ALIGN_TOP_LEFT, 0, 0);
65	
66	  /* Flex 布局 */
67	
68	  lv_obj_set_flex_flow(overlay, LV_FLEX_FLOW_COLUMN);
69	  lv_obj_set_flex_align(overlay, LV_FLEX_ALIGN_CENTER,
70	                        LV_FLEX_ALIGN_CENTER,
71	                        LV_FLEX_ALIGN_CENTER);
72	  lv_obj_set_style_pad_row(overlay, 16, 0);
73	
74	  /* 标题 */
75	
76	  lv_obj_t *title = lv_label_create(overlay);
77	  lv_label_set_text(title, popup_data->title);
78	  lv_obj_set_style_text_color(title, lv_color_hex(0xFFFFFF), 0);
79	
80	  /* 内容 */
81	
82	  lv_obj_t *content = lv_label_create(overlay);
83	  lv_label_set_text(content, popup_data->content);
84	  lv_obj_set_style_text_color(content, lv_color_hex(0xAAAAAA), 0);
85	
86	  /* 关闭按钮 */
87	
88	  lv_obj_t *btn = lv_btn_create(overlay);
89	  lv_obj_set_size(btn, 200, 44);
90	  lv_obj_set_style_bg_color(btn, lv_color_hex(0x00E676), 0);
91	  lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, 0);
92	  lv_obj_set_style_radius(btn, 8, 0);
93	
94	  lv_obj_t *btn_label = lv_label_create(btn);
95	  lv_label_set_text(btn_label, "OK");
96	  lv_obj_set_style_text_color(btn_label, lv_color_hex(0x000000), 0);
97	  lv_obj_center(btn_label);
98	
99	  /* 存储 overlay 指针用于关闭回调 */
100	
101	  lv_obj_set_user_data(btn, overlay);
102	
103	  /* 注册关闭回调 */
104	
105	  lv_obj_add_event_cb(btn, popup_btn_close_cb, LV_EVENT_CLICKED, NULL);
106	  lv_obj_add_event_cb(overlay, popup_overlay_close_cb, LV_EVENT_CLICKED, NULL);
107	
108	  printf("[popup] Displayed: %s\n", popup_data->title);
109	  free(popup_data);
110	}
111	
112	/****************************************************************************
113	 * 显示弹窗
114	 ****************************************************************************/
115	
116	static int show_popup(const char *title, const char *content)
117	{
118	  /* 分配弹窗数据 */
119	
120	  popup_data_t *popup_data = malloc(sizeof(popup_data_t));
121	  if (!popup_data) {
122	    printf("[popup] Error: Memory allocation failed\n");
123	    return -1;
124	  }
125	
126	  /* 复制标题和内容 */
127	
128	  strncpy(popup_data->title, title, sizeof(popup_data->title) - 1);
129	  popup_data->title[sizeof(popup_data->title) - 1] = '\0';
130	  strncpy(popup_data->content, content, sizeof(popup_data->content) - 1);
131	  popup_data->content[sizeof(popup_data->content) - 1] = '\0';
132	
133	  /* 在 LVGL 线程中安全地创建弹窗 */
134	
135	  lv_result_t res = lv_async_call(popup_async_cb, popup_data);
136	  if (res != LV_RESULT_OK) {
137	    free(popup_data);
138	    printf("[popup] Error: lv_async_call failed\n");
139	    return -1;
140	  }
141	
142	  printf("[popup] Scheduled: %s\n", title);
143	  return 0;
144	}
145	
146	/****************************************************************************
147	 * 主函数
148	 ****************************************************************************/
149	
150	int main(int argc, char *argv[])
151	{
152	  printf("=== My AI Tool (team 307) ===\n");
153	
154	  if (argc < 2) {
155	    printf("Usage: my_ai_tool <command>\n");
156	    printf("  hello              - Say hello\n");
157	    printf("  info               - Show system info\n");
158	    printf("  popup <title> <content> - Show popup notification\n");
159	    return 0;
160	  }
161	
162	  if (strcmp(argv[1], "hello") == 0) {
163	    printf("Hello from team 307!\n");
164	  } else if (strcmp(argv[1], "info") == 0) {
165	    printf("Board: lckfb_huangshan_pi (SF32LB52)\n");
166	    printf("Team: 307 justdoit\n");
167	  } else if (strcmp(argv[1], "popup") == 0) {
168	    if (argc < 4) {
169	      printf("Usage: my_ai_tool popup <title> <content>\n");
170	      return -1;
171	    }
172	    return show_popup(argv[2], argv[3]);
173	  } else {
174	    printf("Unknown command: %s\n", argv[1]);
175	  }
176	
177	  return 0;
178	}
