/****************************************************************************
 * 读取当前时间
 ****************************************************************************/

static int get_current_time(int *weekday, int *hour, int *min)
{
  int fd = open("/dev/rtc0", O_RDONLY);
  if (fd < 0)
    {
      printf("ERROR: Cannot open RTC\n");
      return -1;
    }

  struct rtc_time rt;
  int ret = ioctl(fd, RTC_RD_TIME, (unsigned long)&rt);
  close(fd);

  if (ret < 0)
    {
      printf("ERROR: RTC read failed\n");
      return -1;
    }

  if (weekday) *weekday = rt.tm_wday == 0 ? 7 : rt.tm_wday;
  if (hour)    *hour    = rt.tm_hour;
  if (min)     *min     = rt.tm_min;

  return 0;
}

/****************************************************************************
 * 命令实现
 ****************************************************************************/

static void cmd_dump(void)
{
  course_manager_init();
  course_dump();
}

static void cmd_today(void)
{
  course_manager_init();

  int wd, h, m;
  if (get_current_time(&wd, &h, &m) < 0)
    return;

  const char *weekday_names[] =
  {
    "", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"
  };

  printf("\n=== Today: %s %02d:%02d ===\n",
         weekday_names[wd], h, m);

  course_query_t states[10];
  int count = course_get_today_status(wd, h, m,
                                      states, 10);

  if (count == 0)
    {
      printf("No classes today. Enjoy your day off!\n\n");
      return;
    }

  for (int i = 0; i < count; i++)
    {
      const course_t *c = states[i].course;
      if (states[i].is_happening)
        {
          printf("  [%s] %02d:%02d-%02d:%02d  %-20s  %s\n",
                 "IN PROGRESS",
                 c->start_hour, c->start_min,
                 c->end_hour, c->end_min,
                 c->name, c->location);
        }
      else if (states[i].minutes_left < 0)
        {
          printf("  [DONE   ] %02d:%02d-%02d:%02d  %-20s  %s\n",
                 c->start_hour, c->start_min,
                 c->end_hour, c->end_min,
                 c->name, c->location);
        }
      else
        {
          printf("  [IN %3dm] %02d:%02d-%02d:%02d  %-20s  %s\n",
                 states[i].minutes_left,
                 c->start_hour, c->start_min,
                 c->end_hour, c->end_min,
                 c->name, c->location);
        }
    }

  printf("\n");
}

static void cmd_next(void)
{
  course_manager_init();

  int wd, h, m;
  if (get_current_time(&wd, &h, &m) < 0)
    return;

  course_query_t q;
  if (course_get_next(wd, h, &m, &q) < 0)
    {
      printf("No more classes today.\n");
      return;
    }

  const course_t *c = q.course;
  if (q.is_happening)
    {
      printf("Now: %s (%s) - IN PROGRESS\n",
             c->name, c->location);
    }
  else
    {
      printf("Next: %s (%s) at %02d:%02d (%d min)\n",
             c->name, c->location,
             c->start_hour, c->start_min,
             q.minutes_left);
    }
}

static void cmd_test_rtc(void)
{
  int wd, h, m;
  if (get_current_time(&wd, &h, &m) < 0)
    return;

  const char *weekday_names[] =
  {
    "", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"
  };

  printf("RTC: %s %02d:%02d (weekday=%d)\n",
         weekday_names[wd], h, m, wd);
}

static void cmd_help(void)
{
  printf("\n=== Campus Agent (Team 307) ===\n");
  printf("Usage: campus_agent <command>\n\n");
  printf("Commands:\n");
  printf("  dump        Print full course schedule\n");
  printf("  today       Show today's courses with status\n");
  printf("  next        Show next upcoming course\n");
  printf("  test_rtc    Test RTC time reading\n");
  printf("  help        Show this help\n");
  printf("\n");
}

